test("reports a delivered event after one attempt", async () => {
  const post = async () => ({ status: 200 });
  assert.deepStrictEqual(await deliver(post, "https://x.invalid", {}), { delivered: true, attempts: 1 });
});

// Replays `statuses` in order, one per attempt, so a test pins the attempt
// count by how far into the list `deliver` gets.
function postReturning(statuses) {
  let i = 0;
  return async () => ({ status: statuses[i++] });
}

test("retries a 503 and reports the attempt that succeeded", async () => {
  const post = postReturning([503, 200]);
  assert.deepStrictEqual(await deliver(post, "https://x.invalid", {}), { delivered: true, attempts: 2 });
});

